let carrier = $.input.carrier.toLowerCase();
const trackingNumber = $.input.trackingNumber;

// Auto-detect Shippo test tracking numbers
if (trackingNumber.startsWith('SHIPPO_')) carrier = 'shippo';

return { carrier, trackingNumber };

const resp = $.steps.getTracking.response || {};
const status = resp.tracking_status || {};
const history = (resp.tracking_history || []).map(h => ({
  status: h.status || '',
  details: h.status_details || '',
  date: h.status_date || '',
  location: h.location ? `${h.location.city || ''}, ${h.location.state || ''} ${h.location.zip || ''}`.trim() : ''
}));

return {
  trackingNumber: resp.tracking_number || $.input.trackingNumber,
  carrier: resp.carrier || $.input.carrier,
  status: status.status || 'UNKNOWN',
  statusDetails: status.status_details || '',
  statusDate: status.status_date || '',
  location: status.location ? `${status.location.city || ''}, ${status.location.state || ''}` : '',
  eta: resp.eta || '',
  servicelevel: resp.servicelevel?.name || '',
  history,
  summary: `${resp.tracking_number || $.input.trackingNumber}: ${status.status || 'UNKNOWN'} - ${status.status_details || 'No details available'}`
};
